import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { roundCents } from './money.js';

export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => (inv.status === 'issued' || inv.status === 'partially_paid') && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

export function vatSummary(invoices) {
  const vatMap = new Map();

  const filtered = invoices.filter((inv) =>
    inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid'
  );

  for (const invoice of filtered) {
    for (const line of invoice.lines) {
      const lineAmount = line.qty * line.unitPrice;
      const lineDiscount = roundCents(lineAmount * line.discountPercent / 100);
      const lineAfterDiscount = lineAmount - lineDiscount;
      const lineVAT = roundCents(lineAfterDiscount * line.vatRate / 100);

      if (!vatMap.has(line.vatRate)) {
        vatMap.set(line.vatRate, { base: 0, vat: 0 });
      }

      const entry = vatMap.get(line.vatRate);
      entry.base += lineAfterDiscount;
      entry.vat += lineVAT;
    }
  }

  return Array.from(vatMap.entries())
    .map(([rate, { base, vat }]) => ({ rate, base, vat }))
    .sort((a, b) => b.rate - a.rate);
}

export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = roundCents(due * daysOverdue * 0.0004);

  return fee;
}

